attribute vec4 position;
attribute vec4 inputTextureCoordinate;

uniform float texelWidthOffset;
uniform float texelHeightOffset;

varying vec2 textureCoordinate;
varying vec4 textureShift_1;
varying vec4 textureShift_2;
varying vec4 textureShift_3;
varying vec4 textureShift_4;

void main(void)
{
    gl_Position = position;
    textureCoordinate = inputTextureCoordinate.xy;

    vec2 singleStepOffset = vec2(texelWidthOffset, texelHeightOffset);
    textureShift_1 = vec4(textureCoordinate - singleStepOffset,                           textureCoordinate + singleStepOffset);
    textureShift_2 = vec4(textureCoordinate - 2.0 * singleStepOffset,                           textureCoordinate + 2.0 * singleStepOffset);
    textureShift_3 = vec4(textureCoordinate - 3.0 * singleStepOffset,                           textureCoordinate + 3.0 * singleStepOffset);
    textureShift_4 = vec4(textureCoordinate - 4.0 * singleStepOffset,                           textureCoordinate + 4.0 * singleStepOffset);
}

attribute vec4 position;
attribute vec4 inputTextureCoordinate;

const int GAUSSIAN_SAMPLES = 9;

uniform float texelWidthOffset;
uniform float texelHeightOffset;

varying vec2 textureCoordinate;
varying vec2 blurCoordinates[GAUSSIAN_SAMPLES];

void main()
{
 gl_Position = position;
 textureCoordinate = inputTextureCoordinate.xy;

 // Calculate the positions for the blur
 int multiplier = 0;
 vec2 blurStep;
   vec2 singleStepOffset = vec2(texelHeightOffset, texelWidthOffset);

 for (int i = 0; i < GAUSSIAN_SAMPLES; i++)
   {
  multiplier = (i - ((GAUSSIAN_SAMPLES - 1) / 2));
       // Blur in x (horizontal)
       blurStep = float(multiplier) * singleStepOffset;
  blurCoordinates[i] = inputTextureCoordinate.xy + blurStep;
 }
}

precision highp float;
varying lowp vec2 textureCoordinate;

uniform sampler2D inputImageTexture;
uniform lowp float alphaLevel;
uniform vec2 offsetR; 
uniform vec2 offsetG;
uniform vec2 offsetB;

void main()
{
   mediump vec4 fout;
   fout.r = texture2D(inputImageTexture, textureCoordinate + offsetR).r; 
   fout.g = texture2D(inputImageTexture, textureCoordinate + offsetG).g; 
   fout.b = texture2D(inputImageTexture, textureCoordinate + offsetB).b; 
   fout.a = alphaLevel;

    gl_FragColor = fout;
}

precision mediump float;
varying mediump vec2 _uv;
uniform sampler2D inputImageTexture;
uniform float progress;
uniform float ratio;
const float amplitude = 30.0;
const float speed = 30.0;
vec4 getFromColor(in vec2 uv){
    vec2 fromTexture = vec2(uv.x,1.0 - uv.y);
    vec4 fromColor = texture2D(inputImageTexture,fromTexture);
    return fromColor;
}
vec4 getToColor(in vec2 uv){
    vec2 toTexture = vec2(uv.x,1.0-uv.y);
    vec4 toColor = texture2D(inputImageTexture,toTexture);
    return toColor;
}
vec4 transition(vec2 p) {
  vec2 dir = p - vec2(.5);
  float dist = length(dir);

  if (dist > progress) {
    return mix(getFromColor( p), getToColor( p), progress);
  } else {
    vec2 offset = dir * sin(dist * amplitude - progress * speed);
    return mix(getFromColor( p + offset), getToColor( p), progress);
  }
}
void main() {
    gl_FragColor = transition(_uv);
}

precision mediump float;
varying mediump vec2 _uv;
uniform sampler2D inputImageTexture;
uniform float progress;
uniform float ratio;
const float speed = 1.0; // = 1.0;
const float angle = 1.0; // = 1.0;
const float power = 1.5; // = 1.5;
vec4 getFromColor(in vec2 uv){
    vec2 fromTexture = vec2(uv.x,1.0 - uv.y);
    vec4 fromColor = texture2D(inputImageTexture,fromTexture);
    return fromColor;
}
vec4 getToColor(in vec2 uv){
    vec2 toTexture = vec2(uv.x,1.0-uv.y);
    vec4 toColor = texture2D(inputImageTexture,toTexture);
    return toColor;
}
vec4 transition(vec2 uv) {
  vec2 p = uv.xy / vec2(1.0).xy;
  vec2 q = p;
  float t = pow(progress, power)*speed;
  p = p -0.5;
  for (int i = 0; i < 7; i++) {
    p = vec2(sin(t)*p.x + cos(t)*p.y, sin(t)*p.y - cos(t)*p.x);
    t += angle;
    p = abs(mod(p, 2.0) - 1.0);
  }
  abs(mod(p, 1.0));
  return mix(
    mix(getFromColor(q), getToColor(q), progress),
    mix(getFromColor(p), getToColor(p), progress), 1.0 - 2.0*abs(progress - 0.5));
}
void main() {
    gl_FragColor = transition(_uv);
}

